/** @return the entry with the given opcode, or nullptr */
constexpr const Entry* findByOpcode(int32_t opcode) noexcept {
	size_t low = 0;
	size_t high = ENTRIES.size();
	while (low < high) {
		const size_t mid = low + (high - low) / 2;
		if (ENTRIES[mid].opcode < opcode)
			low = mid + 1;
		else
			high = mid;
	}
	return low < ENTRIES.size() && ENTRIES[low].opcode == opcode ? &ENTRIES[low] : nullptr;
}

